1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the owner's {@code customerCode} formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 and
11	 * LAST3 are the upper-cased first three letters of the city and last name, and NNNN is a per-city
12	 * 4-digit zero-padded sequence equal to one more than the owners already in that city. Runs before
13	 * {@link SaveOwner}, so this owner is not yet counted (e.g. 'LON-SMI-0007').
14	 */
15	public class AssignOwnerCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        String city3 = prefix(owner.getCity());
19	        String last3 = prefix(owner.getLastName());
20	        int sequence = cityCount(owner.getCity(), ownerRepository) + 1;
21	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
22	    }
23	
24	    private static String prefix(String value) {
25	        return value.substring(0, Math.min(3, value.length())).toUpperCase(Locale.ROOT);
26	    }
27	
28	    private static int cityCount(String city, OwnerRepository ownerRepository) {
29	        return (int) ownerRepository.findAll().stream()
30	            .filter(existing -> city.equals(existing.getCity()))
31	            .count();
32	    }
33	}
