3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's {@code checkDigit}: the single Luhn check digit (0-9) computed over the digits
7	 * contained in the owner's {@code customerCode}, ignoring any non-digit separators. Purely derived
8	 * from the stored code, so no state is kept.
9	 */
10	public final class CheckDigit {
11	
12	    private CheckDigit() {
13	    }
14	
15	    public static int of(Owner owner) {
16	        String code = owner.getCustomerCode();
17	        int sum = 0;
18	        boolean dbl = true;
19	        for (int i = code.length() - 1; i >= 0; i--) {
20	            char c = code.charAt(i);
21	            if (c < '0' || c > '9') {
22	                continue;
23	            }
24	            int d = c - '0';
25	            if (dbl) {
26	                d *= 2;
27	                if (d > 9) {
28	                    d -= 9;
29	                }
30	            }
31	            sum += d;
32	            dbl = !dbl;
33	        }
34	        return (10 - (sum % 10)) % 10;
35	    }
36	}
