14	public class BuildOwner {
15	
16	    public void service(@RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
17	            throws MissingOwnerFieldsException {
18	        List<String> missing = new ArrayList<>();
19	        require("firstName", request.getFirstName(), missing);
20	        require("lastName", request.getLastName(), missing);
21	        require("address", request.getAddress(), missing);
22	        require("city", request.getCity(), missing);
23	        require("telephone", request.getTelephone(), missing);
24	        if (!missing.isEmpty()) {
25	            throw new MissingOwnerFieldsException(missing);
26	        }
27	        Owner owner = ownerMapper.toOwner(request);
28	        LocalDate effective = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
29	        owner.setRegistrationDate(BusinessDay.nextBusinessDay(effective));
30	        built.set(owner);
31	    }
32	
33	    private static void require(String field, String value, List<String> missing) {
34	        if (value == null || value.isBlank()) {
35	            missing.add(field);
36	        }
37	    }
38	}
