4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's {@code identityKey}: the single value duplicate detection is expressed
9	 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
10	 * telephone is E.164 (see {@link E164Telephone}), the email is lower-cased (empty when absent) and
11	 * the household id groups owners by last name and address (see {@link HouseholdId}). Because the
12	 * telephone is part of the key, two members of one household with different telephones have
13	 * different keys and are both allowed; only owners that collide on the key are duplicates.
14	 */
15	public final class IdentityKey {
16	
17	    private IdentityKey() {
18	    }
19	
20	    public static String of(Owner owner) {
21	        return telephone(owner) + '|' + email(owner) + '|' + HouseholdId.of(owner);
22	    }
23	
24	    static String telephone(Owner owner) {
25	        String telephone = E164Telephone.toE164(owner.getTelephone());
26	        return telephone == null ? "" : telephone;
27	    }
28	
29	    static String email(Owner owner) {
30	        String email = owner.getEmail();
31	        return (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
32	    }
33	}
