2	
3	/**
4	 * Converts a raw telephone into E.164 form: keeps a leading '+' and country code when present,
5	 * otherwise assumes country code '+61' and drops a single leading '0' from the national digits.
6	 * Spaces, dashes and brackets are stripped. Returns {@code null} when the result would not have
7	 * 8 to 15 digits after the '+', or when the national number's length does not match its country
8	 * code ('+61' requires 9 national digits, '+1' requires 10).
9	 */
10	final class E164Telephone {
11	
12	    private E164Telephone() {
13	    }
14	
15	    static String toE164(String raw) {
16	        if (raw == null) {
17	            return null;
18	        }
19	        boolean international = raw.trim().startsWith("+");
20	        String digits = raw.replaceAll("\\D", "");
21	        if (!international) {
22	            if (digits.startsWith("0")) {
23	                digits = digits.substring(1);
24	            }
25	            digits = "61" + digits;
26	        }
27	        if (digits.length() < 8 || digits.length() > 15) {
28	            return null;
29	        }
30	        if (digits.startsWith("61") && digits.length() != 2 + 9) {
31	            return null;
32	        }
33	        if (digits.startsWith("1") && digits.length() != 1 + 10) {
34	            return null;
35	        }
36	        return "+" + digits;
37	    }
38	}
