3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Derives the stable identifier of an owner's household. A household is the set of owners sharing a
12	 * last name and address (compared case-insensitively with collapsed whitespace, exactly as
13	 * {@code RejectDuplicateOwnerHousehold} groups them), so every such owner maps to the same value
14	 * without any stored state. Owners who opt in with {@code sharesHousehold} therefore return the
15	 * same {@code householdId}.
16	 */
17	public final class HouseholdId {
18	
19	    private HouseholdId() {
20	    }
21	
22	    public static String of(Owner owner) {
23	        String key = normalize(owner.getLastName()) + '�' + normalize(owner.getAddress());
24	        try {
25	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
26	            StringBuilder id = new StringBuilder(16);
27	            for (int i = 0; i < 8; i++) {
28	                id.append(String.format("%02X", digest[i]));
29	            }
30	            return id.toString();
31	        }
32	        catch (NoSuchAlgorithmException ex) {
33	            throw new IllegalStateException(ex);
34	        }
35	    }
36	
37	    private static String normalize(String value) {
38	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
39	    }
40	}
