package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives the stable identifier of an owner's household. A household is the set of owners sharing a
 * last name and address (compared case-insensitively with collapsed whitespace, exactly as
 * {@code RejectDuplicateOwnerHousehold} groups them), so every such owner maps to the same value
 * without any stored state. Owners who opt in with {@code sharesHousehold} therefore return the
 * same {@code householdId}.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(Owner owner) {
        String key = normalize(owner.getLastName()) + '�' + normalize(owner.getAddress());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            StringBuilder id = new StringBuilder(16);
            for (int i = 0; i < 8; i++) {
                id.append(String.format("%02X", digest[i]));
            }
            return id.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

